REPLACE INTO `books` (`id`, `category_id`, `title`, `short_name`, `slug`, `isbn`, `image_url`, `published_year`, `annotation`, `created_at`, `updated_at`) VALUES
	(3, 2, 'Sněhulák', NULL, 'snehulak', '978-80-7662-333-0', 'snehulak.jpg', 2012, 'Detektiv Harry Hole pátrá po sériovém vrahovi, který po sobě zanechává sněhuláky.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(4, 2, 'Deset malých černoušků', NULL, 'deset-malych-cernousku', '978-80-242-2577-7', 'deset-malych-cernousku.jpg', 2020, 'Deset lidí je pozváno na odlehlý ostrov a jeden po druhém začínají za záhadných okolností umírat.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(5, 3, 'Osvícení', NULL, 'osviceni', '978-80-7306-413-6', 'osviceni.jpg', 2010, 'Jack Torrance přijímá práci správce v horském hotelu, kde začíná podléhat temným silám.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(6, 3, 'Mlčení jehňátek', NULL, 'mlceni-jehnatek', '978-80-7381-812-8', 'hannibal-lecter-mlceni-jehnatek.jpg', 2010, 'Mladá agentka FBI Clarice Starlingová spolupracuje s vězněným kanibalem dr. Lecterem na dopadení sériového vraha.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(7, 4, 'Babička', NULL, 'babicka', '978-80-7390-280-3', 'babicka.jpg', 2015, 'Babička je nejznámějším dílem Boženy Němcové. Jedná se o novelu, kterou psala v době, kdy jí umíral syn. Autorka zde zachycuje dění na venkově se všemi zvyky. Nejslavnější klasické dílo spisovatelky Boženy Němcové není třeba dlouze představovat. Malebný příběh z venkova 19. století nám vypráví o životě a hodnotách prostých lidí i vrchnosti. Kdo by mohl zapomenout na babičku a její nejoblíbenější vnučku Barunku, paní kněžnu a její schovanku Hortensii či Viktorku a černého vojáka', '2026-09-24 07:20:56', '2026-09-24 12:17:59'),
	(8, 4, 'Krysař', NULL, 'krysar', '978-80-7390-010-6', 'krysar.jpg', 2014, 'Novela na motivy staroněmecké pověsti o krysařovi, lásce, zradě a bezohlednosti.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(9, 5, 'Pýcha a předsudek', NULL, 'pycha-a-predsudek', '978-80-207-1845-7', 'pycha-a-predsudek.jpg', 2018, 'Příběh inteligentní Elizabeth Bennetové a hrdého pana Darcyho plný nedorozumění a společenských konvencí.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(10, 5, 'Než jsem tě poznala', NULL, 'nez-jsem-te-poznala', '978-80-249-2180-8', 'nez-jsem-te-poznala.jpg', 2013, 'Dojemný romance o dívce Lou, která přijme práci pečovatelky u kvadruplegika Willa.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(11, 6, 'Egypťan Sinuhet', NULL, 'egyptan-sinuhet', '978-80-7214-387-0', 'egyptan-sinuhet.jpg', 2008, 'Rozsáhlý historický román zachycující život královského lékaře ve starověkém Egyptě.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(12, 6, 'Jméno růže', NULL, 'jmeno-ruze', '978-80-257-1111-8', 'jmeno-ruze.jpg', 2014, 'Filozoficko-detektivní román ze středověkého opatství, kde dochází k sérii záhadných úmrtí.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(13, 7, 'Pán prstenů: Společenstvo Prstenu', 'Pán prstenů', 'pan-prstenu-spolecenstvo-prstenu', '978-80-257-0740-1', 'pan-prstenu-spolecenstvo-prstenu.jpg', 2012, 'Začátek epického putování hobita Hobbita Jedním prstenem k Hoře osudu.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(14, 7, 'Duna', NULL, 'duna', '978-80-269-1582-9', 'duna.jpg', 2021, 'Sci-fi sága o pouštní planetě Arrakis, kde se bojuje o nejcennější látku ve vesmíru – koření.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(15, 8, 'Velký Gatsby', NULL, 'velky-gatsby', '978-80-207-1563-0', 'velky-gatsby.jpg', 2014, 'Příběh o tajemném milionáři Jayi Gatsby-m a jeho nenaplněné lásce v jazzovém věku.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(16, 8, 'Na západní frontě klid', NULL, 'na-zapadni-fronte-klid', '978-80-249-3665-9', 'na-zapadni-fronte-klid.jpg', 2018, 'Strhující svědectví o hrůzách první světové války pohledem mladého vojáka Paula Bäumera.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(19, 10, 'Máj', NULL, 'maj', '978-80-7390-008-3', 'maj.jpg', 2014, 'Vrcholné dílo českého romantismu o tragické lásce, tragédii a pomíjivosti života.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(20, 10, 'Kytice', NULL, 'kytice', '978-80-7390-006-9', 'kytice.jpg', 2014, 'Sbírka balad vycházejících z českých lidových pověstí a báječných motivů.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(21, 11, 'Steve Jobs', NULL, 'steve-jobs', '978-80-7363-401-8', 'steve-jobs.jpg', 2011, 'Ekskluzivní životopis zakladatele firmy Apple postavený na desítkách rozhovorů.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(22, 11, 'Einstein: Jeho život a vesmír', 'Einstein', 'einstein-jeho-zivot-a-vesmir', '978-80-7363-395-0', 'einstein-jeho-zivot-a-vesmir.jpg', 2012, 'Detailní biografie nejslavnějšího vědce 20. století a jeho objevů.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(23, 12, 'Svět Sofie', NULL, 'svet-sofie', '978-80-7260-270-4', 'svet-sofie.jpg', 2012, 'Románový průvodce dějinami filozofie určený pro mladé i dospělé čtenáře.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(24, 12, 'Tak pravil Zarathustra', NULL, 'tak-pravil-zarathustra', '978-80-7298-251-6', 'tak-pravil-zarathustra.jpg', 2013, 'Filozofické dílo pojednávající o nadčlověku, vůli k moci a věčném návratu.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(25, 13, 'Sapiens: Stručné dějiny lidstva', 'Sapiens', 'sapiens-strucne-dejiny-lidstva', '978-80-7363-631-9', 'sapiens-strucne-dejiny-lidstva.jpg', 2014, 'Fascinující pohled na vývoj člověka od dobe kamenné až po moderní věk.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(26, 13, 'Evropa: Dějiny jednoho kontinentu', 'Evropa', 'evropa-dejiny-jednoho-kontinentu', '978-80-7257-222-9', 'evropa-dejiny-jednoho-kontinentu.jpg', 2005, 'Komplexní a čtivý přehled evropských dějin od pravěku do konce 20. století.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(27, 14, 'Kulturní dějiny klimatu', NULL, 'kulturni-dejiny-klimatu', '978-80-7432-022-4', 'kulturni-dejiny-klimatu.jpg', 2013, 'Podtitul: Od doby ledové po globální oteplování Jak lidský druh v průběhu dějin ovlivnil klima? Jak ovlivňovaly výkyvy klimatu život našich předků? Autor nám fascinujícím způsobem osvětluje všechno, co bychom měli vědět o historických změnách klimatu a jejich kulturních důsledcích od holocenu po 21. století. Jeho vědecký záběr přitom sahá od věd přírodních k vědám společenským, opírá se o geologii, klimatologii, paleontologii, archeologii, o kulturní historii a mnoho dalších oborů. Kniha v roce svého prvního vydání (2007) úspěšně vstoupila na pole současných diskusí o globálním oteplování a do počátku roku 2010 se dočkala již šesti německých a jednoho anglického vydání.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(28, 14, 'Moderní architektura - Nejvýznamnější světové stavby 20. století', 'Moderní architektura', 'moderni-architektura-nejvyznamnejsi-svetove-stavby-20-stoleti', '80-00-01304-5', 'moderni-architektura.jpg', 2000, 'Komplexní průvodce nejznámějšími budovami a stavbami zaznamenává i všechna významná architektonická hnutí a význačné architekty dvacátého století. Kniha je doplněna velkým množstvím barevných fotografií. Vysvětluje také, jak architekturu ovlivňuje historie a rychle se měnící sociální a politická situace.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(29, 15, 'Černobyl: Historie jaderné katastrofy', 'Černobyl', 'cernobyl-historie-jaderne-katastrofy', '978-80-7565-517-2', 'cernobyl-historie-jedne-katastrofy.jpg', 2019, 'Podrobná rekonstrukce tragické havárie v černobylské elektrárně v roce 1986.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(30, 15, 'Svět, který skončil včera: Co se můžeme naučit od tradičních společností?', 'Svět, který skončil včera', 'svet-ktery-skoncil-vcera-co-se-muzeme-naucit-od-tradicnich-spolecnosti', '978-80-87270-97-4', 'svet-ktery-skoncil-vcera.jpg', 2008, 'Svět, který skončil včera: Co se můžeme naučit od tradičních společností? Ačkoliv si o sobě myslíme, jak normální životy žijeme, podle Jareda Diamonda jsme vlastně divní. Převážnou část z šesti milionů let své existence totiž vypadala a fungovala lidská společnost zcela jinak. Na cestě k dnešku jsme měnili mnohé, ale nabízí nám opravdu historie poučení, jak dělat věci lépe? Fascinující kniha s autobiografickými prvky propojující poznatky antropologie a evoluční biologie provokuje, vysvětluje i baví, v každém případě však změní váš pohled na člověka jako živočišný druh.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(33, 17, 'Bohatý táta, chudý táta', NULL, 'bohaty-tata-chudy-tata', '978-80-7349-358-5', 'bohaty-tata-chudy-tata.jpg', 2013, 'Bestseller o finanční gramotnosti, investování a myšlení bohatých lidí.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(34, 17, 'Ekonomie v jednom viru', NULL, 'ekonomie-v-jednom-viru', '978-80-86389-70-7', 'ekonomie-v-jednom-viru.jpg', 2008, 'Klasická kniha srozumitelně vysvětlující základní ekonomické principy.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(35, 18, 'Krátká historie mýtu', NULL, 'kratka-historie-mytu', '80-7203-750-1', 'kratka-historie-mytu.jpg', 2009, 'Krátká historie mýtu se zamýšlí nad mýty a sleduje jejich vývoj od dávnověku do dnešní doby. Co jsou to mýty? Jak vznikaly? A proč vůbec? Mají pro nás ještě nějaký význam? Ztratili jsme k nim vztah? Dějiny mýtu jsou vlastně historií lidstva záznamem jeho nadějí a usilování, jeho pátrání po řádu věcí. Mýty nám pomáhají porozumět vesmíru a našemu místu v něm. Mýty a jejich trvalé proměny nám pomáhají pochopit ty, kdo si tyto příběhy vyprávěli a vytvářeli je. Mýtus nelze číst potichu, pokud mu chceme porozumět. Takový mýtus nemá smysl. Mýtus je třeba žít a prožít. A znovu a znovu ho vyprávět.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(36, 18, 'Život na naší planetě: Mé svědectví a vize pro budoucnost', 'Život na naší planetě', 'zivot-na-nasi-planete-me-svedectvi-a-vize-pro-budoucnost', '978-80-7252-884-4', 'zivot-na-nasi-planete.jpg', 2021, 'Osobní svědectví Davida Attenborougha o stavu naší planety, historii života na Zemi a vizi pro udržitelnou budoucnost lidstva.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(37, 19, '1000 divů Česka - Nejkrásnější výtvory přírody i člověka', '1000 divů Česka', '1000-divu-ceska-nejkrasnejsi-vytvory-prirody-i-cloveka', '978-80-242-2051-2', '1000-divu-ceska-nejkrasnejsi-vytvor.jpg', 2008, 'Průvodce po nejkrásnějších přírodních lokacích České republiky.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(38, 19, 'Národní parky USA - průvodce', 'Národní parky USA', 'narodni-parky-usa-pruvodce', '978-80-256-2528-6', 'narodni-parky-usa-pruvodce.png', 2018, 'Americké národní parky nabízejí jedny z nejpůsobivějších scenérií na této planetě. Šedesát pečlivě střežených výjimečných oblastí jsou výkladní skříní tohoto jedinečného koutu, kde přírodní síly vykouzlily to nejlepší ze své nepřeberné palety.“ Prožijte to nejlepší z národních parků USA Grand Canyon, Yellowstone, Yosemite a dalších téměř šedesát míst vybrali jsme ty nejkrásnější národní parky v USA, kde můžete snadno a stále dokola prozkoumávat přírodní bohatství. Zvláštní kapitoly tipy na pozorování zvířat outdoorové aktivity', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(39, 20, '30 minut v kuchyni', NULL, '30-minut-v-kuchyni', '978-80-905003-0-3', 'snadno-a-rychle.png', 2018, 'Kuchařka s recepty ze pěti ingrediencí připravená během několika minut.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(40, 20, 'Kuchařka pro dceru', NULL, 'kucharka-pro-dceru', '978-80-87049-09-9', 'kucharka-pro-dceru.jpg', 2008, 'Příručka vaření pro začátečníky s podrobnými vysvětleními postupů.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(41, 21, 'Tajný život stromů', NULL, 'tajny-zivot-stromu', '978-80-7299-122-8', 'tajny-zivot-stromu.png', 2016, 'Kniha o tom, jak stromy komunikují, pečují o své potomky a navzájem si pomáhají.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(42, 21, 'Zahrada k sežrání', NULL, 'zahrada-k-sezrani', '978-80-7336-700-0', 'zahrada-k-sezrani.jpg', 2014, 'Praktické rady pro pěstování rostlin podle principů permakultury.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(43, 22, 'Atomové návyky', NULL, 'atomove-navyky', '978-80-271-2244-8', 'atomove-navyky.jpg', 2020, 'Ověřený systém, jak budovat dobré návyky a zbavovat se těch zlozvyků.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(44, 22, 'Čtyřhodinový pracovní týden', NULL, 'ctyrhodinovy-pracovni-tyden', '978-80-87270-02-8', 'ctyrhodinovy-pracovni-tyden.jpg', 2011, 'Návod, jak efektivněji pracovat, delegovat úkoly a získat více volného času.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(47, 24, 'Zrozeni k běhu (Born to Run)', 'Zrozeni k běhu', 'zrozeni-k-behu-born-to-run', '978-80-7363-356-1', 'zrozeni-k-behu.jpg', 2011, 'Příběh o tajném kmeni indiánů Tarahumarů a přirozeném běhání naboso.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(48, 24, 'Fit i bez fitka', NULL, 'fit-i-bez-fitka', '978-80-264-3428-3', 'fit-i-bez-fitka.jpg', 2013, 'K tomu, abyste se dostali do kondice, nepotřebujete zafuněnou posilovnu. Guru českého běhu Miloš Škorpil pro vás ve spolupráci se svou ženou Danou připravil srozumitelný návod na zlepšení fyzičky a budování síly v domácích podmínkách. Jak si rozvrhnout trénink a vyzrát na regeneraci? Co všechno můžete ke cvičení použít? A jak zlepšit svou běžeckou techniku? S racionálním přístupem k pohybu nakopnete svoje výkony a vaše tělo omládne o celé roky!', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(49, 25, 'Jídlo na prvním místě', NULL, 'jidlo-na-prvnim-miste', '978-80-87950-08-1', 'jidlo-na-prvnim-miste.jpg', 2014, 'Metodika Whole30 zaměřená na znovunastavení metabolismu a zdravého stravování.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(50, 25, 'Velmi osobní kniha o zdraví', NULL, 'velmi-osobni-kniha-o-zdravi', '978-80-265-0753-6', 'velmi-osobni-kniha-o-zdravi.jpg', 2018, 'Osobní průvodce zdravým životním stylem od PharmDr. Margit Slimákové s praktickými radami k výživě, pohybu a duševní pohodě.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(51, 26, 'Aha! Rodičovství', NULL, 'aha-rodicovstvi', '978-80-87270-98-1', 'aha-rodicovstvi.jpg', 2015, 'Jak vychovat zodpovědné a emočně vyrovnané děti bez křiku a trestů.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(52, 26, 'Vychováváme děti a rosteme s nimi', NULL, 'vychovavame-deti-a-rosteme-s-nimi', '978-80-7252-287-3', 'vychovavame-deti-a-rosteme-s-nimi.jpg', 2010, 'Pohled na výchovu dětí založený na respektu a empatii, který rodičům pomáhá pochopit vlastní emoce a reakce.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(53, 27, 'Myšlení, rychlé a pomalé', NULL, 'mysleni-rychle-a-pomale', '978-80-7363-429-2', 'mysleni-rychle-a-pomale.png', 2012, 'Přehled dvou systémů, které řídí naše uvažování a rozhodování.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(54, 27, 'Léčba smyslem - Základy a aplikace logoterapie', 'Léčba smyslem', 'lecba-smyslem-zaklady-a-aplikace-logoterapie', '978-80-262-1723-7', 'lecba-smyslem.jpg', 2011, 'Tato kniha je výsledkem série přednášek, kterou měl autor v letním semestru roku 1966 na Jižní metodistické univerzitě v texaském Dallasu. Ústředním pojmem přednášek je logoterapie psychoterapie zaměřená na hledání smyslu lidského života. Frankl zde zdůrazňuje systematickou povahu logoterapie, která předpokládá svobodu vůle, vůli ke smyslu a smysl života. Zaměřuje se na konkrétní logoterapeutické techniky a také na aplikační oblasti logoterapie, jež léčí různé typy neuróz. Logoterapie je kladena do kontextu jiných psychoterapeutických škol a závěrečná kapitola knihy se věnuje i jejímu vztahu k teologii.Viktor E. Frankl (19051997) byl profesorem neurologie a psychiatrie na Vídeňské univerzitě a profesorem logoterapie na United States International University v Kalifornii a dalších amerických univerzitách. Je tvůrcem tzv. logoterapie a existenciální analýzy jakožto třetího vídeňského směru psychoterapie, který se zaměřuje na hledání smyslu v lidském životě. Ve svých knihách Frankl mj. využil své zkušenosti vězně nacistických koncentračních táborů. V Portále vyšly jeho knihy Utrpení z nesmyslnosti života a Teorie a terapie neuróz.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(57, 29, 'Faktomluva', NULL, 'faktomluva', '978-80-7565-388-8', 'faktomluva.jpg', 2018, 'Deset důvodů, proč se mýlíme v pohledu na svět a proč je to lepší, než si myslíme.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(58, 29, 'Mžik', NULL, 'mzik', '978-80-265-0381-1', 'mzik.jpg', 2015, 'O tom, jak fungují naše bleskové úsudky a první dojmy a proč jim někdy můžeme, ale jindy nemůžeme důvěřovat.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(59, 30, 'Jak věci fungují', NULL, 'jak-veci-funguji', '978-80-242-5813-3', 'jak-veci-funguji.jpg', 2017, 'Ilustrovaný průvodce stovkami strojů, mechanismů a technologií.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(60, 30, 'Ilustrovaná encyklopedie starého Egypta', NULL, 'ilustrovana-encyklopedie-stareho-egypta', '80-7184-446-2', 'ilustrovana-encyklopedie.jpg', 2012, 'Rozsáhlé původní dílo vědců Českého egyptologického ústavu. Úvodní dvě kapitoly jsou věnovány historii Egypta a egyptologii. Těžiště práce pak představuje více než 950 abecedně uspořádaných hesel týkajících se politických poměrů, hospodářství, náboženství, jazyka a písma, literatury, umění, významných osobností a událostí staroegyptské historie. Knihu doplňuje přes 600 ilustračních obrázků.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(61, 31, 'Ztracený oceán: Omalovánky', 'Ztracený oceán', 'ztraceny-ocean-omalovanky', '978-80-265-0453-5', 'ztraceny-ocean-omalovanky.jpg', 2015, 'Detailní relaxační omalovánky zaměřené na podmořský svět.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(62, 31, 'Čarovný les', NULL, 'carovny-les', '978-80-265-0300-2', 'carovny-les.jpg', 2015, 'Antistresové omalovánky pro dospělé plné přírodních motivů.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(63, 32, 'Pohádky', NULL, 'pohadky', '978-80-00-02334-2', 'pohadky.jpg', 2009, 'Klasické příběhy jako Malá mořská víla, Cínový vojáček nebo Ošklivé kachňátko.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(64, 32, 'Pohádky tisíce a jedné noci', NULL, 'pohadky-tisice-a-jedne-noci', '978-80-00-02000-6', 'pohadky-tisice-a-jedne-noci.jpg', 2010, 'Tradiční arabské vyprávění Šeherezády o Aladinovi či Sindibádovi.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(65, 33, 'Rychlé šípy', NULL, 'rychle-sipy', '978-80-7033-524-6', 'rychle-sipy.png', 2018, 'Souborné vydání legendárního českého komiksu o klubu pěti chlapců.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(66, 33, 'Maus', NULL, 'maus', '978-80-7381-999-6', 'maus.jpg', 2012, 'Pulitzerovou cenou oceněný grafický román o holokaustu se zvířecími postavami.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(67, 34, 'Z deníku kocoura Modroočka', NULL, 'z-deniku-kocoura-modroocka', '978-80-00-04122-3', 'z-deniku-kocoura-modroocka.png', 2015, 'Příběh mladého kocoura poznávajícího svět kolem sebe psaný velkým písmem.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(68, 34, 'Honzíkova cesta', NULL, 'honzikova-cesta', '978-80-00-03200-7', 'honzikova_cesta.jpg', 2013, 'Tradiční kniha pro začínající čtenáře o chlapci, který jede sám k babičce na venkov.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(71, 36, 'Písanka 1 pro 1. ročník ZŠ', NULL, 'pisanka-1-pro-1-rocnik-zs', '978-80-7235-401-6', 'pisanka-1-pro-1-rocnik-zs.jpg', 2010, 'Cvičebnice psaní prvních písmen a slov.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(72, 36, 'Procvičujeme vyjmenovaná slova', NULL, 'procvicujeme-vyjmenovana-slova', '978-80-264-1111-3', 'procvicujeme-vyjmenovana-slova.jpg', 2016, 'Sešit plný doplňovaček a cvičení na českou gramatiku.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(73, 37, 'Návrhové vzory (Design Patterns)', 'Návrhové vzory', 'navrhove-vzory-design-patterns', '978-80-251-1582-4', 'navrhove-vzory.png', 2007, 'Základní literatura zaměřená na objektově orientovaný návrh softwaru.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(74, 37, 'Čistý kód: Návrhové vzory, refaktorování, testování a další techniky agilního programování', 'Čistý kód', 'cisty-kod-navrhove-vzory-refaktorovani-testovani-a-dalsi-techniky-agilniho-programovani', '978-80-251-2285-3', 'cisty-kod.jpg', 2009, 'Příručka pro programátory jak psát čitelný, udržovatelný a kvalitní kód.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(75, 38, 'Angličtina Časté gramatické chyby', NULL, 'anglictina-caste-gramaticke-chyby', '978-80-247-3401-9', 'anglictina-caste-gramaticke-chyby.jpg', 2019, 'V této cvičebnici se naučíte správně používat anglické tvary a vyhýbat se typickým gramatickým chybám. Pozornost věnujeme především oblastem gramatiky, kde se nejčastěji dělají chyby – mimo jiné jsou to časy, Present Perfect, průběhové tvary sloves, vyjadřování budoucnosti, členy, otázky a tázací dovětky, věty s if, infinitiv a gerundium, modální slovesa a předložky. Vyzkoušejte si, co vám dělá problémy!Více než 100 rozmanitých a zábavných cvičení prověří vaše znalosti. Otestujte, co umíte dobře, a co byste si měli zopakovat. Přehled správných řešení všech cvičení vám umožní samostatnou kontrolu. Edice Procvičujeme si je vhodná k učení a opakování doma i na cestách.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(76, 38, 'Angličtina pro samouky', NULL, 'anglictina-pro-samouky', '978-80- LED-100-2', 'anglictina-pro-samouky.jpg', 2015, 'Tradiční česká učebnice pro samostatné studium anglického jazyka.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(77, 39, 'Němčina pro samouky I.', NULL, 'nemcina-pro-samouky-i', '978-80-200-1811-3', 'nemcina-pro-samouky.jpg', 2009, 'Přehledná učebnice němčiny pro samouky se zaměřením na základní gramatiku a slovní zásobu, vhodná pro samostatné studium.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(78, 39, 'Sprechen Sie Deutsch?', NULL, 'sprechen-sie-deutsch', '978-80-86713-00-7', 'sprechen-sie-deutsch.jpg', 2010, 'Čtyřdílný kurz německého jazyka určený pro střední školy.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(79, 40, 'Česko-anglický slovník / Czech-English dictionary', 'Česko-anglický slovník', 'cesko-anglicky-slovnik-czech-english-dictionary', '80-85600-29-3', 'cesko-anglicky-slovnik.jpg', 1993, 'Praktický oboustranný slovník obsahující aktuální zásobu slov i frazeologii.', '2026-09-24 07:20:56', '2026-09-24 12:09:58'),
	(80, 40, 'Slovník cizích slov', NULL, 'slovnik-cizich-slov', '978-80-7184-000-0', 'slovnik-cizich-slov.jpg', 2010, 'Přehledný výkladový slovník cizích výrazů používaných v češtině.', '2026-09-24 07:20:56', '2026-09-24 12:09:58');
